class Solution {
  public int maxSumAfterOperation(int[] nums) {
    // plain: best subarray ending here without squaring; squared: with exactly one square used
    long plain = 0, squared = 0, best = Long.MIN_VALUE;
    for (int x : nums) {
      long sq = (long) x * x;
      squared = Math.max(Math.max(plain + sq, squared + x), sq);
      plain = Math.max(plain + x, x);
      best = Math.max(best, squared);
    }
    return (int) best;
  }
}
